<?php
declare(strict_types=1);
return static function(PDO$pdo):void{
 $pdo->exec("CREATE TABLE program_manual_entities(id INT AUTO_INCREMENT PRIMARY KEY,program_manual_id INT NOT NULL,entity_type ENUM('Staff','Committee') NOT NULL,source_key VARCHAR(190) NOT NULL,source_label VARCHAR(255) NOT NULL,source_detail TEXT NULL,sort_order INT NOT NULL DEFAULT 0,UNIQUE KEY uq_manual_entity(program_manual_id,entity_type,source_key),CONSTRAINT fk_manual_entity_manual FOREIGN KEY(program_manual_id) REFERENCES program_manuals(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $pdo->exec("CREATE TABLE program_manual_mappings(id INT AUTO_INCREMENT PRIMARY KEY,program_manual_id INT NOT NULL,source_type ENUM('Course','PLO','Staff','Committee') NOT NULL,source_record_id INT NOT NULL,target_record_id INT NULL,match_method VARCHAR(50) NULL,confidence DECIMAL(5,2) NOT NULL DEFAULT 0,status ENUM('Suggested','Confirmed','Rejected','Missing') NOT NULL DEFAULT 'Suggested',reviewed_by_user_id INT NULL,reviewed_at DATETIME NULL,UNIQUE KEY uq_manual_mapping(program_manual_id,source_type,source_record_id),KEY idx_manual_mapping_status(status),CONSTRAINT fk_manual_mapping_manual FOREIGN KEY(program_manual_id) REFERENCES program_manuals(id) ON DELETE CASCADE,CONSTRAINT fk_manual_mapping_reviewer FOREIGN KEY(reviewed_by_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $pdo->exec("CREATE TABLE program_manual_notifications(id INT AUTO_INCREMENT PRIMARY KEY,program_manual_id INT NOT NULL,notification_type VARCHAR(100) NOT NULL,message VARCHAR(500) NOT NULL,due_date DATE NULL,status ENUM('Open','Dismissed') NOT NULL DEFAULT 'Open',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_manual_notification(program_manual_id,notification_type,message),CONSTRAINT fk_manual_notification_manual FOREIGN KEY(program_manual_id) REFERENCES program_manuals(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
};
